export const APPS={terminal:{label:'Terminal · Kitty',icon:'⌘',command:['kitty']},browser:{label:'Browser · Firefox',icon:'◎',command:['firefox']},files:{label:'Files · Thunar',icon:'▣',command:['thunar']},music:{label:'Music · player',icon:'♫',command:['playerctl','play-pause']},settings:{label:'Audio settings',icon:'⚙',command:['pavucontrol']},network:{label:'Network settings',icon:'⌁',command:['nm-connection-editor']},bluetooth:{label:'Bluetooth settings',icon:'ᛒ',command:['blueman-manager']},calculator:{label:'Calculator',icon:'⊞',command:['qalculate-gtk']},lock:{label:'Lock session',icon:'◇',command:['hyprlock']}};
export const ICONS=['','◈','⌘','◎','▣','♫','⚙','◷','⌁','ᛒ','▰','♧','⊞','◉','⏻','◇','☀','☾'];
export const THEMES={Amethyst:{background:'#11111b',fill:'#181825',color:'#cdd6f4',accent:'#cba6f7'},Ocean:{background:'#071a24',fill:'#0d2b3b',color:'#dcf4fa',accent:'#67d9ee'},Forest:{background:'#101a16',fill:'#1c2c24',color:'#e0eee4',accent:'#9fd6a0'},Rose:{background:'#20131e',fill:'#332032',color:'#f5deeb',accent:'#f3a8d0'}};
export function actionId(item){if(item.actionId)return item.actionId;return Object.keys(APPS).find(k=>APPS[k].command.join(' ')===item.action)||'';}
export function unresolved(project){return project.elements.flatMap(e=>(e.options?.items||[]).filter(i=>!APPS[actionId(i)]).map(i=>`${e.name}: ${i.label||'Unnamed shortcut'}`));}
export const TYPE_META={bar:['▤','Bar'],dock:['▣','Dock'],widget:['⬡','Custom widget'],text:['T','Text'],shape:['◆','Shape'],clock:['◷','Clock'],workspaces:['▦','Workspaces'],volume:['♪','Volume'],brightness:['☀','Brightness'],network:['⌁','Network'],bluetooth:['ᛒ','Bluetooth'],battery:['▰','Battery'],notifications:['♧','Notifications'],launcher:['⊞','Applications'],music:['♫','Music'],visualizer:['≋','Music waves'],cpu:['◈','CPU'],memory:['▥','Memory'],memoryChart:['⌁','Memory graph'],gpu:['◇','GPU'],temperature:['♨','Temperature'],disk:['◫','Disk'],uptime:['⌁','Uptime'],power:['⏻','Power']};
export function isContainer(e){return e?.type==='bar'||e?.type==='dock'||e?.type==='widget';}
